-- Verification.identifier holds OAuth state tokens, password-reset tokens and
-- other one-off values generated by Better Auth — never a user email. The
-- foreign key to User(email) made every social sign-in fail with P2003 the
-- moment Better Auth stored a state value, so it has to go.
DROP INDEX IF EXISTS "Verification_identifier_idx";
ALTER TABLE "Verification" DROP CONSTRAINT IF EXISTS "Verification_identifier_fkey";
CREATE INDEX "Verification_identifier_idx" ON "Verification"("identifier");
